/* Modules de gestion : simulation en mémoire, aucun flux clinique ou financier réel. */
(function(root){
'use strict';
const overlap=(a,b)=>a.start<b.end&&b.start<a.end;
function bookingError(rows,item){
 if(!item.patient||!item.resource||!item.start||!item.end||!Number.isFinite(Date.parse(item.start))||!Number.isFinite(Date.parse(item.end))||item.end<=item.start)return 'Renseignez le séjour, la ressource et une fin postérieure au début.';
 const collision=rows.find(x=>x.state!=='Annulée'&&x.state!=='Terminée'&&overlap(x,item)&&(x.resource===item.resource||x.patient===item.patient));
 return collision?'Conflit avec '+collision.id+' : ressource ou patient déjà réservé.':'';
}
function dispenseError(lot,qty,today){
 if(!lot||!Number.isInteger(qty)||qty<=0)return 'La quantité doit être un nombre entier positif.';
 if(lot.blocked)return 'Lot bloqué : dispensation interdite.';
 if(lot.expiry<today)return 'Lot périmé : dispensation bloquée.';
 if(qty>lot.quantity)return 'Stock insuffisant.';
 return '';
}
function invoiceTotals(lines){const cents=lines.reduce((n,x)=>n+Math.round(Number(x.price)*100)*Number(x.qty),0);return cents/100;}
const api={overlap,bookingError,dispenseError,invoiceTotals};
if(typeof module!=='undefined')module.exports=api;
root.createClinicManagement=function(ctx){
 const {$,esc,patients,sectors,toast}=ctx;
 const labels={regulation:'Bloc & lits',pharmacy:'Circuit du médicament',activity:'Activité',pmsi:'PMSI',billing:'Facturation'};
 const resources=Object.entries(sectors).flatMap(([sector,label])=>Array.from({length:2},(_,i)=>({id:sector+'-'+(i+1),sector,label:label+' · '+(sector.startsWith('bloc')?'Salle':sector.startsWith('sspi')?'Poste':'Place')+' '+(i+1)})));
 const vacations=[],reservations=[],lots=[],movements=[],acts=[],pmsi=new Map(),invoices=new Map();let seq=1,stayId=patients[0]?.id,current='regulation';
 const today=()=>new Intl.DateTimeFormat('fr-CA',{timeZone:'Europe/Paris',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
 const now=()=>{const d=new Date();return new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,16)};
 const canWrite=()=>ctx.canWrite?ctx.canWrite(current):ctx.role()!=='Infirmier';
 const getStay=()=>patients.find(x=>x.id===stayId)||patients[0];
 const money=n=>new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR'}).format(n);
 function options(values,value){return values.map(v=>{const [id,label]=Array.isArray(v)?v:[v,v];return `<option value="${esc(id)}" ${id===value?'selected':''}>${esc(label)}</option>`}).join('')}
 function field(name,label,type='text',value='',attrs='required'){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`}
 function select(name,label,values,value){return `<label>${label}<select name="${name}">${options(values,value)}</select></label>`}
 function form(id,body,button){return canWrite()?`<form id="${id}" class="management-form"><div class="formgrid">${body}</div><p role="alert" class="management-error"></p><button class="primary">${button}</button></form>`:'<p class="notice">Profil infirmier : consultation des modules de gestion en lecture seule.</p>'}
 function table(headers,rows){return rows.length?`<div class="management-scroll"><table class="management-table"><thead><tr>${headers.map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'<p class="empty">Aucun enregistrement pour cette sélection.</p>'}
 function trace(stay,text){stay?.events.unshift({at:new Date().toLocaleString('fr-FR'),role:ctx.role(),kind:'Gestion · simulation',text})}
 function submit(id,fn){const f=$('#'+id);if(f)f.onsubmit=e=>{e.preventDefault();if(!canWrite())return;const error=fn(Object.fromEntries(new FormData(f)));if(error){f.querySelector('[role=alert]').textContent=error;return}render(current);toast('Modification préparée · vérifiez la confirmation serveur')};}
 function openStay(id,tab){ctx.open(id,tab)}
 function actions(){document.querySelectorAll('[data-management-dossier]').forEach(b=>b.onclick=()=>openStay(b.dataset.managementDossier,b.dataset.tab||'consult'))}
 function card(title,text){return `<article class="management-metric"><strong>${esc(title)}</strong><span>${esc(text)}</span></article>`}
 function render(key){current=key;$('#stats').hidden=true;$('#new').hidden=true;if(!patients.some(x=>x.id===stayId))stayId=patients[0]?.id;ctx.stats();$('#title').textContent=labels[key];document.querySelectorAll('.nav[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===key));$('#workspace').innerHTML=`<section class="panel management"><div class="content"><p class="eyebrow">GESTION DE L’ÉTABLISSEMENT</p><h2>${labels[key]}</h2><p class="notice">Simulation · données fictives, formulaires enregistrés dans le dossier partagé. Aucune transmission externe.</p><div class="management-toolbar ui-stay-bar">${(()=>{const st=getStay(),n=st?.identity||{};return st?`<div class="ui-stay-id"><span class="ui-avatar" aria-hidden="true">${esc((((n.lastName||'')[0]||'')+((n.firstName||'')[0]||'')).toUpperCase()||'?')}</span><span class="ui-who"><strong>${esc(n.lastName?String(n.lastName).toUpperCase()+' '+(n.firstName||''):st.id)}</strong><span>${esc(st.id)} · ${esc(st.specialty)} · ${esc(st.mode||'')} · ${esc(st.stage||'')}</span></span></div>`:''})()}${select('management-stay','Changer de séjour',patients.map(x=>[x.id,x.id+' · '+[x.identity?.lastName,x.identity?.firstName].filter(Boolean).join(' ')+' · '+x.specialty]),stayId)}<button class="secondary" data-management-dossier="${esc(stayId)}">Ouvrir le dossier</button></div><div id="management-body"></div></div></section>`;
 $('select[name="management-stay"]').onchange=e=>{stayId=e.target.value;render(key)};
 ({regulation,pharmacy,activity,pmsi:renderPmsi,billing})[key]();actions();}
 const planner=root.createBlocPlanner({$,esc,patients,sectors,resources,reservations,vacations,toast,filters:ctx.filters,today,now,canWrite,access:ctx.access,getStay,open:openStay,trace:(id,message)=>{if(['anesthesiste','chirurgien'].includes(ctx.access?.()?.profile.profession))trace(patients.find(p=>p.id===id),message)}});
 function regulation(){planner.render()}
 let medicineTab='analysis';
 function pharmacy(){
 const stay=getStay();if(!stay){$('#management-body').innerHTML='<p>Aucun séjour sélectionné.</p>';return}
 const tabs=[['analysis','Analyse'],['reconciliation','Conciliation'],['validation','Validation pharmaceutique'],['dispensing','Dispensation'],['administration','Administration'],['stock','Stocks']];
 $('#management-body').innerHTML=`<div class="tabs" aria-label="Étapes du circuit du médicament">${tabs.map(([key,label])=>`<button data-medicine-tab="${key}" aria-pressed="${medicineTab===key}" class="${medicineTab===key?'active':''}">${label}</button>`).join('')}</div><div id="medicine-panel"></div>`;
 document.querySelectorAll('[data-medicine-tab]').forEach(b=>b.onclick=()=>{medicineTab=b.dataset.medicineTab;render(current)});
 if(['stock','dispensing'].includes(medicineTab)){const parent=$('#management-body');const panel=$('#medicine-panel');panel.id='management-body';parent.removeAttribute('id');stockPharmacy();return}
 const rows=(stay.rx||[]).map((r,i)=>({r,i})).filter(x=>x.r.category==='Médicament');
 const records=stay.medicationCircuit||[];
 const fingerprint=r=>JSON.stringify(Object.fromEntries(Object.entries(r).filter(([k])=>!['executions','administered'].includes(k))));
 const validation=(r,i)=>records.filter(x=>x.kind==='validation'&&x.rx===i&&x.fingerprint===fingerprint(r)).at(-1);
 const job=ctx.access?.()?.profile.profession;
 const canReview=['anesthesiste','chirurgien','pharmacien'].includes(job);
 const canValidate=job==='pharmacien';
 const rxOptions=rows.map(({r,i})=>[String(i),r.name]);
 const text=(name,label)=>`<label class="wide">${label}<textarea name="${name}" required maxlength="3000"></textarea></label>`;
 const reviewForm=(kind,body,button,allowed)=>allowed?`<form id="medicine-review" class="management-form"><div class="formgrid">${body}${field('author','Auteur fictif de la revue','text','','required maxlength="100"')}</div><p role="alert" class="management-error"></p><button class="primary">${button}</button></form>`:'<p class="notice">Lecture seule. Cette étape nécessite un compte habilité'+(kind==='validation'?' de pharmacien.':'.')+'</p>';
 let html='';
 if(medicineTab==='analysis'){
 const names=rows.map(x=>x.r.name.trim().toLocaleLowerCase('fr'));const duplicates=names.filter((x,i)=>names.indexOf(x)!==i);
 html=`<h3>Analyse documentée des prescriptions</h3><p>Contrôles humains : allergies, interactions, doublons, dose, voie, fréquence, durée, poids et fonction rénale. Aucun moteur automatisé d’interactions ou d’adaptation posologique n’est connecté.</p><p><strong>Allergies saisies :</strong> ${esc(stay.consult?.data?.allergies||stay.consult?.allergies||'À vérifier dans la consultation')}</p>${duplicates.length?'<p class="notice warn">Libellés identiques repérés : '+esc([...new Set(duplicates)].join(', '))+'. Vérification nécessaire.</p>':''}${table(['Prescription','Consignes','Validation médicale','Revue pharmaceutique'],rows.map(({r,i})=>[esc(r.name),esc(r.instructions),r.validated?'Validée en simulation':'Brouillon',esc(validation(r,i)?.status||'En attente')]))}${rows.length?reviewForm('analysis',select('rx','Prescription analysée',rxOptions)+select('status','Conclusion',['À clarifier','Intervention proposée','Analyse documentée'])+text('note','Analyse, éléments vérifiés, référence et conduite proposée'),'Enregistrer l’analyse',canReview):'<p>Ajoutez une prescription dans le dossier.</p>'}`;
 } else if(medicineTab==='reconciliation'){
 const meds=(stay.consult?.medicationRows||[]).filter(m=>!m.removed);
 html=`<h3>Conciliation aux transitions</h3><p>Comparez le traitement habituel, les prescriptions du séjour et le traitement de sortie. Documentez les divergences et la reprise prévue.</p>${table(['Traitement habituel','Dose / fréquence / voie','Source','Conduite / reprise'],meds.map(m=>[esc(m.name),esc([m.dose,m.frequency,m.route].filter(Boolean).join(' · ')),esc(m.source||m.verification),esc([m.decision,m.resumePlan].filter(Boolean).join(' · '))]))}${reviewForm('reconciliation',select('transition','Transition',['Entrée','Transfert','Sortie'])+field('drug','Traitement concerné')+text('sources','Sources confrontées et dates')+select('status','Divergence',['À clarifier','Divergence intentionnelle documentée','Divergence non intentionnelle corrigée','Concordance documentée'])+text('note','Traitement retenu, motif, arrêt / reprise et responsable'),'Enregistrer la conciliation',canReview)}<button class="secondary" data-management-dossier="${esc(stayId)}" data-tab="consult">Revoir les traitements habituels</button>`;
 } else if(medicineTab==='validation'){
 html=`<h3>Validation pharmaceutique distincte de la validation médicale</h3><p>Seul le compte ayant le métier Pharmacien peut enregistrer cette décision. Une modification de la prescription rend la revue antérieure non applicable.</p>${table(['Prescription','Validation médicale','Statut pharmaceutique'],rows.map(({r,i})=>[esc(r.name),r.validated?'Validée':'Brouillon',esc(validation(r,i)?.status||'En attente')]))}${rows.some(x=>x.r.validated)?reviewForm('validation',select('rx','Prescription médicalement validée',rxOptions.filter(([i])=>stay.rx[Number(i)].validated))+select('status','Décision',['Validée en simulation','Intervention en attente de réponse','À revoir'])+text('note','Vérifications, intervention et réponse du prescripteur'),'Enregistrer la décision pharmaceutique',canValidate):'<p>Aucune prescription médicalement validée.</p>'}`;
 } else {
 const perop=(stay.perop?.records||[]).filter(x=>x.kind==='Médicament'&&!x.voided);
 html=`<h3>Administrations du séjour</h3><p>Les doses réellement administrées restent distinctes des quantités dispensées et des unités de stock.</p>${table(['Prescription','Statut / horaire','Dose / voie','Auteur / motif'],rows.flatMap(({r})=>(r.executions||[]).map(e=>[esc(r.name),esc(e.status)+' · '+esc(e.at),esc([e.dose,e.route].filter(Boolean).join(' · ')),esc(e.author)+' · '+esc(e.note)])))}<h3>Administrations peropératoires</h3>${table(['Horaire','Médicament','Dose / débit','Voie'],perop.map(e=>[esc(e.at),esc(e.values?.drug),esc([e.values?.amount,e.values?.unit].filter(Boolean).join(' ')),esc(e.values?.route)]))}<button class="secondary" data-management-dossier="${esc(stayId)}" data-tab="rx">Tracer une administration ou une non-administration</button>`;
 }
 const shown=records.filter(x=>x.kind===medicineTab);
 $('#medicine-panel').innerHTML=html+`<h3>Historique de cette étape</h3>${table(['Saisie','Prescription / traitement','Conclusion','Détail / auteur'],shown.slice().reverse().map(x=>[esc(x.at),esc(x.drug||stay.rx[x.rx]?.name||''),esc(x.status),esc(x.note)+' · '+esc(x.author)+(x.sources?'<br>'+esc(x.sources):'')]))}`;
 const f=$('#medicine-review');if(f)f.onsubmit=e=>{e.preventDefault();if(medicineTab==='validation'?!canValidate:!canReview)return;const v=Object.fromEntries(new FormData(f));if(!v.author.trim()||!v.note.trim())return;const r=stay.rx[Number(v.rx)];if(medicineTab==='validation'&&!r?.validated)return;const entry={...v,id:crypto.randomUUID(),kind:medicineTab,at:new Date().toISOString(),account:ctx.access?.()?.profile.user_id||'',rx:v.rx===undefined?null:Number(v.rx),fingerprint:r?fingerprint(r):''};(stay.medicationCircuit??=[]).push(entry);trace(stay,'Circuit du médicament · '+medicineTab+' · '+v.status);render(current);toast('Revue préparée · vérifiez la confirmation serveur')};
 }
 function stockPharmacy(){
 const rx=(getStay()?.rx||[]).map((r,i)=>({r,i})).filter(x=>x.r.category==='Médicament'&&x.r.validated&&(getStay().medicationCircuit||[]).filter(v=>v.kind==='validation'&&v.rx===x.i&&v.fingerprint===JSON.stringify(Object.fromEntries(Object.entries(x.r).filter(([k])=>!['executions','administered'].includes(k))))).at(-1)?.status==='Validée en simulation');
 $('#management-body').innerHTML=`<p>Stock par présentation et lot. Dispensation accessible après validation pharmaceutique. La dispensation reste distincte de l’administration tracée dans le dossier infirmier. Aucun contrôle automatique d’interaction ou de posologie n’est réalisé ici.</p><div class="management-metrics">${card(lots.length,'lots enregistrés')}${card(lots.filter(l=>l.expiry<today()).length,'lots périmés bloqués')}${card(rx.length,'prescriptions validées médicalement et pharmaceutiquement')}</div><h3>Réception d’un lot</h3>${form('receive',field('drug','Présentation exacte / code CIS ou CIP','text','','required maxlength="160"')+field('batch','Numéro de lot','text','','required maxlength="80"')+field('expiry','Péremption','date')+field('quantity','Quantité en unités de conditionnement','number','1','required min="1" step="1"')+field('unit','Unité de stock','text','boîte','required maxlength="40"')+field('threshold','Seuil d’alerte de stock','number','2','required min="0" step="1"'), 'Réceptionner le lot')}<h3>Stock disponible</h3>${table(['Présentation','Lot / péremption','Quantité','Alerte'],lots.map(l=>[esc(l.drug),esc(l.batch)+'<br>'+esc(l.expiry),esc(l.quantity)+' '+esc(l.unit),(l.blocked?'Bloqué':l.expiry<today()?'Périmé':l.quantity<=l.threshold?'Stock bas':'Disponible')+(canWrite()?` <button class="secondary" data-block-lot="${l.id}">${l.blocked?'Débloquer':'Bloquer'}</button>`:'')]))}<h3>Dispenser pour ${esc(stayId)}</h3>${rx.length&&lots.length?form('dispense',select('rx','Prescription médicale validée',rx.map(({r,i})=>[String(i),r.name]))+select('lot','Lot à dispenser',lots.map(l=>[l.id,l.drug+' · '+l.batch]))+field('quantity','Quantité en unités de stock','number','1','required min="1" step="1"')+field('author','Pharmacien / préparateur fictif','text','','required maxlength="80"')+field('check','Vérification de correspondance','checkbox','yes','required'), 'Tracer la dispensation simulée'):'<p class="notice">Ajoutez un lot et une prescription de médicament validée médicalement puis pharmaceutiquement dans le dossier pour tester la dispensation.</p>'}<button class="secondary" data-management-dossier="${esc(stayId)}" data-tab="rx">Voir les prescriptions et administrations</button><h3>Mouvements du séjour</h3>${table(['Date','Prescription','Lot','Quantité','Auteur'],movements.filter(m=>m.patient===stayId).map(m=>[esc(m.at),esc(m.rxName),esc(m.batch),esc(m.quantity)+' '+esc(m.unit),esc(m.author)]))}`;
 document.querySelectorAll('[data-block-lot]').forEach(b=>b.onclick=()=>{if(!canWrite())return;const lot=lots.find(l=>l.id===b.dataset.blockLot);lot.blocked=!lot.blocked;trace(getStay(),'Lot '+lot.batch+' · '+(lot.blocked?'bloqué':'débloqué'));render(current)});
 submit('receive',v=>{v.drug=v.drug.trim();v.batch=v.batch.trim();const quantity=Number(v.quantity),threshold=Number(v.threshold);if(!v.drug||!v.batch||!v.expiry||v.expiry<today()||!Number.isInteger(quantity)||quantity<=0||!Number.isInteger(threshold)||threshold<0)return 'Vérifiez les champs, les quantités et la péremption.';if(lots.some(l=>l.drug===v.drug&&l.batch===v.batch))return 'Lot déjà enregistré : utilisez un nouveau numéro pour cette simulation.';lots.push({...v,id:'LOT-'+crypto.randomUUID(),quantity,threshold});});
 submit('dispense',v=>{const lot=lots.find(l=>l.id===v.lot),quantity=Number(v.quantity),r=getStay().rx[Number(v.rx)];const err=dispenseError(lot,quantity,today());if(err)return err;if(!rx.some(x=>x.i===Number(v.rx))||!r?.validated||r.category!=='Médicament'||v.check!=='yes'||!v.author.trim())return 'Vérifiez la prescription, la correspondance du lot et l’auteur.';lot.quantity-=quantity;movements.unshift({at:now(),patient:stayId,rxName:r.name,batch:lot.batch,quantity,unit:lot.unit,author:v.author});trace(getStay(),'Dispensation simulée · '+r.name+' · lot '+lot.batch)});
 }
 function activity(){
 const rows=acts.filter(a=>a.patient===stayId);
 $('#management-body').innerHTML=`<p>Recueil manuel des actes réalisés, reliés au séjour. Les codes saisis ne sont pas vérifiés contre une nomenclature officielle et aucun tarif n’est déduit.</p>${form('act',select('type','Nomenclature',['CCAM','NGAP','Autre'])+field('code','Code saisi manuellement','text','','required maxlength="30"')+field('label','Libellé de l’acte','text','','required maxlength="160"')+field('date','Date de réalisation','date',today())+field('performer','Exécutant fictif','text','','required maxlength="80"')+field('qty','Quantité','number','1','required min="1" step="1"'),'Enregistrer un acte réalisé')}<h3>Activité du séjour</h3>${table(['Date','Nomenclature / code','Acte','Exécutant','Quantité','État'],rows.map(a=>[esc(a.date),esc(a.type)+' · '+esc(a.code),esc(a.label),esc(a.performer),esc(a.qty),esc(a.state)+(canWrite()&&a.state==='Actif'?` <button class="secondary" data-void-act="${a.id}">Annuler</button>`:'')]))}<p>${rows.filter(a=>a.state==='Actif').length} ligne(s) active(s) pour ce séjour.</p>`;
 submit('act',v=>{if(!v.code.trim()||!v.label.trim()||!v.performer.trim()||!Number.isInteger(Number(v.qty))||Number(v.qty)<=0)return 'Code, libellé, exécutant et quantité entière positive requis.';acts.push({...v,qty:Number(v.qty),id:'ACT-'+crypto.randomUUID(),patient:stayId,state:'Actif'});const doc=pmsi.get(stayId);if(doc)doc.state='Brouillon';trace(getStay(),'Acte saisi · '+v.code)});
 document.querySelectorAll('[data-void-act]').forEach(b=>b.onclick=()=>{if(!canWrite())return;const a=acts.find(x=>x.id===b.dataset.voidAct);a.state='Annulé';const doc=pmsi.get(stayId);if(doc)doc.state='Brouillon';trace(getStay(),'Acte annulé · '+a.code);render(current)});
 }
 function renderPmsi(){
 const d=pmsi.get(stayId)||{state:'Brouillon'},rows=acts.filter(a=>a.patient===stayId&&a.state==='Actif');
 $('#management-body').innerHTML=`<p class="notice">Préparation au codage DIM · aucun groupage GHM/GHS, aucun RSS/RSA réglementaire généré et aucun envoi ATIH. Les codes CIM-10 doivent être vérifiés par le DIM.</p><p><span class="pill">${esc(d.state)}</span></p>${form('pmsi-edit',field('entry','Entrée','date',d.entry)+field('exit','Sortie','date',d.exit)+field('unit','Unité médicale','text',d.unit)+field('dp','Diagnostic principal · code CIM-10','text',d.dp)+field('dr','Diagnostic relié · si pertinent','text',d.dr,'maxlength="30"')+field('das','Diagnostics associés · codes séparés par des virgules','text',d.das,'maxlength="500"')+field('reviewer','Codeur DIM fictif','text',d.reviewer,'required maxlength="80"')+select('state','État du dossier',['Brouillon','Prêt pour revue DIM'],d.state),'Enregistrer le dossier de codage')}<h3>Activité liée au séjour</h3>${table(['Code','Libellé','Date'],rows.map(a=>[esc(a.code),esc(a.label),esc(a.date)]))}<p>La complétude vérifiée ici concerne les champs du prototype ; la validité médico-économique du codage reste à contrôler.</p>${d.entry?`<button class="secondary" id="pmsi-export">Exporter le brouillon JSON de travail</button>`:''}`;
 submit('pmsi-edit',v=>{if(!v.entry||!v.exit||v.exit<v.entry||!v.unit.trim()||!v.dp.trim()||!v.reviewer.trim())return 'Entrée, sortie cohérente, unité, diagnostic principal et codeur requis.';pmsi.set(stayId,{...v,at:now()});trace(getStay(),'PMSI · '+v.state)});
 if($('#pmsi-export'))$('#pmsi-export').onclick=()=>{const blob=new Blob([JSON.stringify({usage:'BROUILLON DE TRAVAIL NON REGLEMENTAIRE',stay:stayId,coding:d,acts:rows},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='PMSI-DEMO-'+stayId+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
 }
 function billing(){
 let doc=invoices.get(stayId);if(!doc){doc={lines:[],state:'Brouillon',payer:'À renseigner',number:'SIM-'+stayId};invoices.set(stayId,doc)}const locked=doc.state==='Validée en simulation';
 $('#management-body').innerHTML=`<p class="notice">Facture illustrative · tarifs saisis manuellement, sans calcul GHS, contrôle conventionnel, télétransmission ni encaissement réel.</p><div class="management-metrics">${card(money(invoiceTotals(doc.lines)),'total saisi')}${card(doc.state,'état de la facture')}${card(doc.payer,'destinataire / payeur')}</div>${!locked?form('payer',select('payer','Destinataire / payeur',['À renseigner','Patient','Assurance maladie','Complémentaire','Établissement'],doc.payer),'Enregistrer le destinataire'):''}${!locked?form('invoice-line',select('act','Acte source facultatif',[['','Ligne libre'],...acts.filter(a=>a.patient===stayId&&a.state==='Actif').map(a=>[a.id,a.code+' · '+a.label])])+field('label','Libellé facturé','text','','required maxlength="160"')+field('qty','Quantité','number','1','required min="1" step="1"')+field('price','Prix unitaire en euros','number','','required min="0" max="1000000" step="0.01"'),'Ajouter une ligne'):''}<h3>${esc(doc.number)}</h3>${table(['Libellé','Quantité','Prix unitaire','Montant','Action'],doc.lines.map((l,i)=>[esc(l.label),esc(l.qty),money(l.price),money(invoiceTotals([l])),!locked&&canWrite()?`<button class="secondary" data-remove-line="${i}">Retirer</button>`:'Verrouillée']))}<p class="management-total">Total : ${money(invoiceTotals(doc.lines))}</p><div class="actions">${canWrite()?locked?'<button class="secondary" id="reopen-invoice">Rouvrir le brouillon</button>':'<button class="primary" id="validate-invoice">Valider en simulation</button>':''}<button class="secondary" id="print-invoice">Imprimer le document de démonstration</button></div><h3>Suivi des règlements fictifs</h3>${form('payment',select('status','État du règlement',['Non réglée','Partiellement réglée','Réglée en simulation'],doc.payment||'Non réglée')+field('paid','Montant reçu simulé (€)','number',doc.paid||'0','required min="0" step="0.01"'),'Enregistrer le règlement fictif')}<p>${esc(doc.payment||'Non réglée')} · ${money(doc.paid||0)} · reste ${money(Math.max(0,invoiceTotals(doc.lines)-(doc.paid||0)))}</p>`;
 submit('payer',v=>{doc.payer=v.payer;trace(getStay(),'Destinataire de facture modifié')});
 submit('invoice-line',v=>{if(locked)return 'Rouvrez le brouillon.';if(!v.label.trim()||!Number.isInteger(Number(v.qty))||Number(v.qty)<=0||!Number.isFinite(Number(v.price))||Number(v.price)<0)return 'Libellé, quantité entière positive et montant positif ou nul requis.';doc.lines.push({...v,qty:Number(v.qty),price:Number(v.price)});trace(getStay(),'Ligne de facture ajoutée')});
 document.querySelectorAll('[data-remove-line]').forEach(b=>b.onclick=()=>{if(!canWrite()||locked)return;doc.lines.splice(Number(b.dataset.removeLine),1);trace(getStay(),'Ligne de facture retirée');render(current)});
 $('#print-invoice').onclick=()=>{const w=window.open('','_blank');if(!w){toast('Autorisez la fenêtre d’impression');return}w.opener=null;w.document.write('<!doctype html><html lang="fr"><meta charset="utf-8"><title>Facture de démonstration</title><style>body{font:16px system-ui;margin:40px}table{border-collapse:collapse;width:100%}td,th{text-align:left;padding:12px;border-bottom:1px solid #ccc}</style><h1>Clinique du Trocadéro</h1><h2>FACTURE DE DÉMONSTRATION — SANS VALEUR COMPTABLE</h2><p>'+esc(doc.number)+' · Séjour fictif '+esc(stayId)+' · '+esc(doc.state)+'</p><p>Destinataire : '+esc(doc.payer)+'</p>'+table(['Libellé','Quantité','Prix unitaire','Montant'],doc.lines.map(l=>[esc(l.label),esc(l.qty),money(l.price),money(invoiceTotals([l]))]))+'<h3>Total : '+money(invoiceTotals(doc.lines))+'</h3><p>Tarifs illustratifs saisis manuellement. Aucun paiement réel.</p></html>');w.document.close();w.focus();w.print()};
 submit('payment',v=>{const paid=Number(v.paid),total=invoiceTotals(doc.lines);if(!Number.isFinite(paid)||paid<0||paid>total)return 'Le règlement doit être compris entre zéro et le total.';if((v.status==='Non réglée'&&paid!==0)||(v.status==='Partiellement réglée'&&(paid<=0||paid>=total))||(v.status==='Réglée en simulation'&&(paid!==total||total===0)))return 'Le statut et le montant du règlement doivent correspondre.';doc.payment=v.status;doc.paid=paid;trace(getStay(),'Règlement fictif · '+money(paid))});
 if($('#validate-invoice'))$('#validate-invoice').onclick=()=>{if(!canWrite())return;if(!doc.lines.length||doc.payer==='À renseigner'){toast('Ajoutez une ligne et renseignez le destinataire');return}doc.state='Validée en simulation';trace(getStay(),'Facture validée en simulation');render(current)};
 if($('#reopen-invoice'))$('#reopen-invoice').onclick=()=>{if(!canWrite())return;doc.state='Brouillon';trace(getStay(),'Facture rouverte en brouillon');render(current)};
 submit('payment',v=>{const paid=Number(v.paid),total=invoiceTotals(doc.lines);if(!Number.isFinite(paid)||paid<0||paid>total||(v.status==='Non réglée'&&paid!==0)||(v.status==='Réglée en simulation'&&paid!==total)||(v.status==='Partiellement réglée'&&(paid<=0||paid>=total)))return 'Le montant doit correspondre au statut et rester compris entre zéro et le total.';doc.payment=v.status;doc.paid=paid;trace(getStay(),'Règlement fictif · '+v.status)});
 $('#print-invoice').onclick=()=>{const w=window.open('','_blank');if(!w){toast('Autorisez l’ouverture de la fenêtre d’impression');return}w.document.write(`<!doctype html><html lang="fr"><meta charset="utf-8"><title>Facture de démonstration</title><style>body{font:16px system-ui;padding:40px}table{border-collapse:collapse;width:100%}th,td{padding:12px;border:1px solid #aaa;text-align:left}</style><h1>DOCUMENT DE DÉMONSTRATION</h1><p>Sans valeur de facturation · aucun paiement demandé</p><h2>Clinique du Trocadéro · ${esc(doc.number)}</h2><p>Séjour fictif ${esc(stayId)} · ${esc(doc.payer)} · ${esc(doc.state)}</p>${table(['Libellé','Quantité','Prix unitaire','Montant'],doc.lines.map(l=>[esc(l.label),esc(l.qty),money(l.price),money(invoiceTotals([l]))]))}<h2>Total illustratif : ${money(invoiceTotals(doc.lines))}</h2></html>`);w.document.close();w.focus();w.print()};
 }
 return {has:key=>Object.hasOwn(labels,key),render,exportState:()=>({planningResources:resources,vacations,reservations,lots,movements,acts,pmsi:[...pmsi],invoices:[...invoices]}),importState:data=>{if(Array.isArray(data.planningResources))resources.splice(0,resources.length,...data.planningResources);vacations.splice(0,vacations.length,...(data.vacations||[]));for(const [key,array]of Object.entries({reservations,lots,movements,acts}))array.splice(0,array.length,...(data[key]||[]));pmsi.clear();invoices.clear();for(const row of data.pmsi||[])pmsi.set(...row);for(const row of data.invoices||[])invoices.set(...row);}};
};
})(typeof window!=='undefined'?window:globalThis);
